START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261030141311_AddAIChatHistory') THEN
    ALTER TABLE "MembershipPackages"
    ADD COLUMN IF NOT EXISTS "PackageType" character varying(20) NOT NULL DEFAULT 'Standard';
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261030141311_AddAIChatHistory') THEN
    CREATE TABLE "AIChatHistories" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "UserId" integer NOT NULL,
        "Question" character varying(1000) NOT NULL,
        "Answer" text NOT NULL,
        "CreatedAt" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_AIChatHistories" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_AIChatHistories_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261030141311_AddAIChatHistory') THEN
    CREATE INDEX "IX_AIChatHistories_UserId_Id" ON "AIChatHistories" ("UserId", "Id");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261030141311_AddAIChatHistory') THEN
    INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20261030141311_AddAIChatHistory', '10.0.12');
    END IF;
END $EF$;
COMMIT;

